insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('4ba253a8-a956-4797-a19a-8de886fd7e51', 'b4850570-003d-4b4f-a008-03c64bd6372e', $$Kanon bv verwerft 15% van de aandelen Acé boven de gemiddelde koers$$,
   $$bedrijfseconomie-havo-2021-i-kanon-bv-context1.png$$,
   $$Het ICT bedrijf Kanon bv wil zeggenschap verwerven binnen een software-ontwikkelingsbedrijf: Ace. Hierdoor kunnen de belangen van Kanon beter gewaarborgd worden. Kanon verwerft op 30 november 2020 15% van de geplaatste aandelen van Acé tegen de beurskoers € 8,60 per aandeel Acé. Deze beurskoers ligt 37% boven de gemiddelde koers van Acé van de laatste 12 maanden voor het overnamebod.$$, 'inline'),
  ('256abcc3-d0ea-450e-b926-ecaf7002efc2', 'b4850570-003d-4b4f-a008-03c64bd6372e', $$inleiding deel van de creditzijde van de balans van Acé$$,
