  ('e7e9d3a7-9a54-4580-a5a7-209cbfc373d7', '4c18c0e0-9f90-46c5-b590-0d7ae4b2abd4', $$inleiding: informatiebronnen 1 en 2; btw buiten beschouwing$$,
